        public ?string $class = null,
    ) {}

    public function getSvg(): string
    {
        return match (strtolower(trim($this->department))) {
            'computer science' => $this->getComputerScienceSvg(),
            'applied physics' => $this->getAppliedPhysicsSvg(),
            'bio-chemistry', 'biochemistry' => $this->getBiochemistrysSvg(),
            default => $this->getDefaultSvg(),
        };
